import gurobipy as gp
from gurobipy import GRB

# Create a new environment and model
env = gp.Env()
model = gp.Model(env=env)

# Sets
I = [1, 2, 3]  # Industries
J = [1, 2, 3, 4, 5]  # Shops

# Parameters
c = {
    1: [4, 9, 2, 6, 5],
    2: [2, 6, 1, 7, 9],
    3: [2, 4, 9, 8, 3]
}
C = {1: 60, 2: 30, 3: 45}
d = [15, 35, 20, 5, 40]

# Decision variables
x = {}
for i in I:
    for j in J:
        x[i][j] = model.addVar(vtype=GRB.CONTINUOUS, lb=0)

# Objective function
model.setObjective(
    sum(c[i][j-1] * x[i][j] for i in I for j in J),
    GRB.MINIMIZE
)

# Constraints
for i in I:
    model.addConstr(
        sum(x[i][j] for j in J) <= C[i]
    )

for j in J:
    model.addConstr(
        sum(x[i][j] for i in I) == d[j-1]
    )

# Optimize the model
model.optimize()

# Check if solution is optimal and report total cost
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
else:
    print("No solution found")

import gurobipy as gp
from gurobipy import GRB

# Read data from problem statement
coords = {
    'DC': (0, 0),
    'S1': (-5, 4), 'S2': (3, 6), 'S3': (-2, -3), 'S4': (4, -2), 
    'S5': (-4, -5), 'S6': (6, 3), 'S7': (-3, 5), 'S8': (5, -4), 
    'S9': (-6, -2), 'S10': (2, 7), 'S11': (-1, -6), 'S12': (4, 5)
}

demands = {
    'S1': 800, 'S2': 600, 'S3': 900, 'S4': 700, 
    'S5': 500, 'S6': 850, 'S7': 750, 'S8': 600, 
    'S9': 450, 'S10': 800, 'S11': 550, 'S12': 700
}

time_windows = {
    'S1': (420, 540), 'S2': (480, 600), 'S3': (450, 570), 
    'S4': (510, 630), 'S5': (540, 660), 'S6': (420, 540), 
    'S7': (480, 600), 'S8': (570, 690), 'S9': (480, 600), 
    'S10': (450, 570), 'S11': (540, 660), 'S12': (510, 630)
}

unloading_times = {
    'S1': 20, 'S2': 15, 'S3': 25, 'S4': 20, 
    'S5': 15, 'S6': 25, 'S7': 20, 'S8': 15, 
    'S9': 15, 'S10': 20, 'S11': 15, 'S12': 20
}

# Create distance matrix
nodes = ['DC'] + [f'S{i}' for i in range(1, 13)]
D = {i: {} for i in nodes}
for i in nodes:
    for j in nodes:
        if i == j:
            D[i][j] = 0
        else:
            x1, y1 = coords[i]
            x2, y2 = coords[j]
            distance = ((x1 - x2)**2 + (y1 - y2)**2)**0.5
            D[i][j] = round(distance, 2)

# Create model
env = gp.Env()
model = gp.Model(env=env)
model.setParam(GRB.Param.TimeLimit, 3600)  # 1 hour time limit

# Variables
x = {}
a = {}
t = {}

for v in range(1, 6):
    for j in nodes[1:]:  # Exclude DC
        x[(v, j)] = model.addVar(vtype=GRB.BINARY, name=f'x_{v}_{j}')

    a[(v, 'DC')] = model.addVar(lb=0, ub=720, name=f'a_v{v}_DC')
    t[(v, 'DC')] = model.addVar(lb=0, ub=720, name=f't_v{v}_DC')

# Objective function
obj = 0
for v in range(1, 6):
    obj += D['DC']['DC']  # This is zero, just to initialize
    for j in nodes[1:]:
        if x.get((v, j)) is not None:
            obj += D['DC'][j]
            prev = j
            next_j = [k for k in nodes[1:] if k != prev and x.get((v, k)) is not None][0]  # Simplified route construction
            obj += D[prev][next_j]

model.setObjective(obj, GRB.MINIMIZE)

# Constraints

# Each supermarket visited exactly once
for j in nodes[1:]:
    model.addConstr(sum(x[(v, j)] for v in range(1,6)) == 1, f'VisitOnce_{j}')

# Capacity constraints
for v in range(1,6):
    total_demand = sum(demands[j] * x.get((v, j), 0) for j in nodes[1:])
    model.addConstr(total_demand <= 3000, f'Capacity_v{v}')

# Time window constraints
for v in range(1,6):
    for j in nodes[1:]:
        if x.get((v, j)) is not None:
            s_j = time_windows[j][0]
            t_j = time_windows[j][1]
            u_j = unloading_times[j]
            model.addConstr(a[(v, j)] >= s_j, f'TimeWindowStart_v{v}_{j}')
            model.addConstr(a[(v, j)] + u_j <= t_j, f'TimeWindowEnd_v{v}_{j}')

# Vehicle departure and return times
for v in range(1,6):
    # Departure after 6:30 AM (390 minutes)
    model.addConstr(t[(v, 'DC')] >= 390, f'DepartureTime_v{v}')
    # Return before 12:00 PM (720 minutes)
    model.addConstr(a[(v, 'DC')] <= 720, f'ReturnTime_v{v}')

# Optimize
model.optimize()

if model.status == GRB.Status.OPTIMAL:
    print(f'FINAL_OBJECTIVE={model.objVal}')
else:
    print('No optimal solution found')

