costs = {'Long-term':240, 'Short-term':390, 
         'Shared':220, 'Promotional':190}

# Availability matrix
availability = {
    'Long-term': {w:1 for w in W},
    'Short-term': {w:1 for w in W},
    'Shared': {w:1 if w in [2,4,5] else 0 for w in W},
    'Promotional': {w:1 if w >=4 else 0 for w in W}
}

# Decision variables
x = {}
for f in F:
    if f == 'Long-term':
        x[f] = model.addVar(vtype=GRB.BINARY, name=f)
    else:
        if f == 'Promotional':
            ub = 2
        else:
            ub = None
        x[f] = model.addVar(ub=ub, name=f)

# Objective function
model.addObjective(
    sum(costs[f] * x[f] for f in F),
    GRB.MINIMIZE
)

# Constraints
for w in W:
    model.addConstr(
        sum(availability[f][w] * x[f] for f in F) == demand[w],
        name=f'Demand_{w}'
    )

# Promotional constraint
model.addConstr(
    x['Promotional'] <= 2,
    name='Max_Promotional'
)

model.optimize()

if model.status == GRB.OPTIMAL:
    total_cost = model.objVal
    print(f'FINAL_OBJECTIVE={total_cost}')
else:
    print('No optimal solution found')
