import gurobipy as gp
from gurobipy import GRB

env = None  # This will be provided by the runtime environment
model = gp.Model(env=env)

# Sets
M = ['M1', 'M2', 'M3', 'M4', 'M5']
J = ['J1', 'J2', 'J3', 'J4']

# Parameters for each job's steps and required machines
processing_times = {
    'J1': {1: ('M1', 3), 2: ('M2', 2), 3: ('M5', 4)},
    'J2': {1: ('M3', 4), 2: ('M4', 3), 3: ('M5', 2)},
    'J3': {1: ('M2', 3), 2: ('M1', 5), 3: ('M4', 2)},
    'J4': {1: ('M1', 2), 2: ('M3', 3), 3: ('M4', 4)}
}

# Decision variables
S = {}
for j in J:
    S[j] = {}
    for s, (m, _) in processing_times[j].items():
        S[j][s] = model.addVar(name=f'S_{j}_{s}', lb=0)

# Objective function
model.setObjective(
    sum(S[j][len(processing_times[j])] + processing_times[j][len(processing_times[j])][1] for j in J),
    GRB.MINIMIZE
)

# Constraints
for m in M:
    # Machine availability constraints
    machine_vars = []
    for j in J:
        for s, (mach, _) in processing_times[j].items():
            if mach == m:
                machine_vars.append((j, s, S[j][s], S[j][s] + processing_times[j][s][1]))
    # Sort by start time and add precedence constraints
    sorted_jobs = sorted(machine_vars, key=lambda x: x[2])
    for i in range(len(sorted_jobs) - 1):
        model.addConstr(
            sorted_jobs[i+1][2] >= sorted_jobs[i][3],
            f'Machine_{m}_order'
        )

for j in J:
    steps = list(processing_times[j].keys())
    for s in steps[1:]:
        prev_step = steps[s-1]
        curr_step = steps[s]
        m_prev, t_prev = processing_times[j][prev_step]
        m_curr, t_curr = processing_times[j][curr_step]
        if m_prev == m_curr:
            model.addConstr(
                S[j][s] >= S[j][s-1] + t_prev,
                f'Precedence_{j}_{s}'
            )

model.optimize()

if model.status == GRB.OPTIMAL:
    total_completion = sum(S[j][len(processing_times[j])].x + processing_times[j][len(processing_times[j])][1] for j in J)
    print(f"FINAL_OBJECTIVE={total_completion}")
