import gurobipy as gp
from gurobipy import GRB

def main(env):
    # Create model
    model = gp.Model(env=env)

    # Sets and indices
    T = [1, 2]
    P = ['X', 'Y']

    # Parameters
    d = {('X', 1): 100, ('X', 2): 300,
         ('Y', 1): 200, ('Y', 2): 100}
    M = 1500
    r = {'X':4, 'Y':3}
    c = {1:300, 2:450}
    s = 100
    i = {'X':200, 'Y':300}
    e = {'X':0.85, 'Y':0.95}
    eb = 0.9

    # Variables
    P_Xt = { (p,t): model.addVar(name=f'P_{p}_t{t}') for p in P for t in T }
    P_Yt = { (p,t): model.addVar(name=f'P_{p}_t{t}') for p in P for t in T }
    I_Xt = { (p,t): model.addVar(name=f'I_{p}_t{t}') for p in P for t in T }
    I_Yt = { (p,t): model.addVar(name=f'I_{p}_t{t}') for p in P for t in T }
    Lt = { t: model.addVar(name=f'L_t{t}') for t in T }

    # Objective
    obj = 0
    for t in T:
        obj += c[t] * Lt[t]
        obj += s * (I_Xt[('X',t)] + I_Yt[('Y',t)])
    model.setObjective(obj, GRB.MINIMIZE)

    # Constraints
    # Demand satisfaction
    for p in P:
        for t in T:
            model.addConstr(i[p] + P_{p,t} >= d[(p,t)], name=f'demand_{p}_t{t}')

    # Production capacity
    for t in T:
        model.addConstr(P_Xt[('X',t)] + P_Yt[('Y',t)] <= M, name=f'production_cap_t{t}')

    # Raw material usage and purchase
    for t in T:
        model.addConstr(Lt[t] == r['X'] * P_Xt[('X',t)] + r['Y'] * P_Yt[('Y',t)], name=f'material_usage_t{t}')
        model.addConstr(Lt[t] <= 2500, name=f'material_purchase_limit_t{t}')

    # Storage constraints
    for p in P:
        for t in T:
            if p == 'X':
                model.addConstr(I_Xt[('X',t)] == i['X'] + P_Xt[('X',t)] - d[('X',t)], name=f'invent_{p}_t{t}')
            else:
                model.addConstr(I_Yt[('Y',t)] == i['Y'] + P_Yt[('Y',t)] - d[('Y',t)], name=f'invent_{p}_t{t}')

    # Efficacy requirement
    for t in T:
        total_production = P_Xt[('X',t)] + P_Yt[('Y',t)]
        if total_production > 0:
            model.addConstr( (e['X'] * P_Xt[('X',t)] + e['Y'] * P_Yt[('Y',t)]) / total_production >= eb, name=f'efficacy_t{t}')

    # Non-negativity
    for p in P:
        for t in T:
            model.addConstr(P_{p,t} >= 0, name=f'non_neg_prod_{p}_t{t}')
            model.addConstr(I_{p,t} >= 0, name=f'non_neg_invent_{p}_t{t}')
    for t in T:
        model.addConstr(Lt[t] >= 0, name=f'non_neg_material_t{t}')

    # Optimize
    model.optimize()

    if model.status == GRB.OPTIMAL:
        total_cost = model.objVal
        print(f"FINAL_OBJECTIVE={total_cost}")
    else:
        print("No optimal solution found.")

if __name__ == "__main__":
    env = gp.Env()
    main(env)
