from gurobipy import GRB

def main(env):
    # Create a new model
    m = gp.Model(env=env)

    # Sets
    M = [1, 2, 3, 4]
    D = [1, 2, 3, 4]

    # Parameters
    F0 = 50000
    R = {1: 20000, 2: 25000, 3: 30000, 4: 35000}
    E = {1: 15000, 2: 35000, 3: 22000, 4: 28000}
    r = {1: 0.002, 2: 0.008, 3: 0.015, 4: 0.03}

    # Decision variables
    x = {}
    for m in M:
        for d in D:
            x[m,d] = m.addVar(lb=0)

    # Objective function
    obj = F0 + sum(R[m] for m in M) - sum(E[m] for m in M)
    for m in M:
        for d in D:
            obj += x[m,d].getAttr(GRB.Attr.Obj, (1 + r[d]))
    m.setObjective(obj, GRB.MAXIMIZE)

    # Constraints
    for m in M:
        lhs = sum(x[m,d] for d in D)
        rhs = F0 + sum(R[k] for k in range(1, m)) - sum(E[k] for k in range(1, m))
        m.addConstr(lhs <= rhs, f"Month_{m}")

    # Optimize the model
    m.optimize()

    if m.status == GRB.Status.OPTIMAL:
        print(f"FINAL_OBJECTIVE={round(m.objVal, 2)}")
    else:
        print("No optimal solution found.")

if __name__ == "__main__":
    env = gp.Env()
    main(env)
