# Decision variables
x_vars = {}
for i in N:
    for j in N:
        if i != j:
            x_vars[i, j] = model.addVar(vtype=GRB.BINARY, name=f'x_{i}_{j}')

y_vars = {}
for i in customers:
    for j in customers:
        if i == j:
            continue
        for k in customers:
            if k == i or k == j:
