import gurobipy as gp
from gurobipy import GRB

env = None  # Use the runtime-provided environment
model = gp.Model(env=env)

# Sets
C = ['C1', 'C2', 'C3', 'C4', 'C5']
W = ['W1', 'W2', 'W3']

# Distance matrix
d = {
    'W1': {'C1': 10, 'C2': 15, 'C3': 12, 'C4': 8, 'C5': 20},
    'W2': {'C1': 8, 'C2': 10, 'C3': 15, 'C4': 12, 'C5': 18},
    'W3': {'C1': 12, 'C2': 8, 'C3': 10, 'C4': 15, 'C5': 12}
}

# Variables
x = {w: model.addVar(vtype=GRB.BINARY, name=f"x_{w}") for w in W}
y = {
    w: {
        c: model.addVar(vtype=GRB.BINARY, name=f"y_{w}_{c}")
        for c in C
    }
    for w in W
}

# Objective
model.setObjective(
    sum(d[w][c] * y[w][c] for w in W for c in C),
    GRB.MINIMIZE
)

# Constraints
# Constraint 1: Exactly two warehouses selected
model.addConstr(sum(x[w] for w in W) == 2, "SelectExactlyTwoWarehouses")

# Constraint 2: Each customer is served by at least one warehouse
for c in C:
    model.addConstr(sum(y[w][c] for w in W) >= 1, f"ServeCustomer_{c}")

# Constraint 3: A warehouse can only serve a customer if it's selected
for w in W:
    for c in C:
        model.addConstr(y[w][c] <= x[w], f"WarehouseSelection_{w}_{c}")

# Constraint 4: Assign each customer to the nearest selected warehouse
for c in C:
    for w1 in W:
        for w2 in W:
            if w1 != w2 and d[w1][c] < d[w2][c]:
                model.addConstr(
                    y[w2][c] <= (d[w1][c] - d[w2][c]) + x[w1],
                    f"NearestWarehouse_{w1}_{w2}_{c}"
                )

model.optimize()

# Output the minimal total distance
print(f"FINAL_OBJECTIVE={model.objVal}")
