def main(env):
    # Create model
    model = gp.Model(env=env)

    # Sets
    C = ['C1', 'C2', 'C3', 'C4']
    T = ['T1', 'T2', 'T3']

    # Parameters: processing times
    p = {
        ('C1','T1'): 2, ('C1','T2'): 3, ('C1','T3'): 1,
        ('C2','T1'): 4, ('C2','T2'): 2, ('C2','T3'): 3,
        ('C3','T1'): 1, ('C3','T2'): 5, ('C3','T3'): 2,
        ('C4','T1'): 3, ('C4','T2'): 2, ('C4','T3'): 4
    }

    # Decision variables: start times
    S = {}
    for c in C:
        for t in T:
            S[c,t] = model.addVar(name=f'S_{c}_{t}', lb=0)

    # Objective function
    Z = None
    F = {}
    for c in C:
        for t in T:
            F[c,t] = S[c,t] + p[(c,t)]
            if Z is None or F[c,t].ub < Z.ub:
                Z = model.addVar(name=f'Z', lb=0)
                model setObjective(Z, GRB.MINIMIZE)
    # Set objective to minimize the maximum F
    for c in C:
        for t in T:
            model.addConstraint(F[c,t] <= Z)

    # Truck Capacity Constraints
    for t in T:
        customers = list(C)
        for i in range(len(customers)):
            for j in range(i+1, len(customers)):
                c1 = customers[i]
                c2 = customers[j]
                model.addConstraint(S[c1,t] + p[(c1,t)] <= S[c2,t] or S[c2,t] + p[(c2,t)] <= S[c1,t])

    # Customer Constraints
    for c in C:
        trucks = list(T)
        for i in range(len(trucks)):
