    model = gp.Model(env=env)

    # Sets
    T = ['Truck1', 'Truck2', 'Truck3', 'Truck4']
    L = ['Loc1', 'Loc2', 'Loc3', 'Loc4']

    # Cost matrix
    C = {
        'Truck1': {'Loc1': 120, 'Loc2': 150, 'Loc3': 180, 'Loc4': 90},
        'Truck2': {'Loc1': 110, 'Loc2': 140, 'Loc3': 170, 'Loc4': 80},
        'Truck3': {'Loc1': 130, 'Loc2': 160, 'Loc3': 190, 'Loc4': 100},
        'Truck4': {'Loc1': 140, 'Loc2': 170, 'Loc3': 200, 'Loc4': 110}
    }

    # Decision variables
    x = {}
    for t in T:
        for l in L:
            x[t, l] = model.addVar(vtype=GRB.BINARY, name=f"x_{t}_{l}")

    # Objective function
    obj = gp.LinExpr()
    for t in T:
        for l in L:
            obj += C[t][l] * x[t, l]
    model.setObjective(obj, GRB.MINIMIZE)

    # Constraints
    for t in T:
        sum_l = gp.LinExpr()
        for l in L:
            sum_l += x[t, l]
        model.addConstr(sum_l == 1, f"Assign_one_location_{t}")

    for l in L:
        sum_t = gp.LinExpr()
        for t in T:
            sum_t += x[t, l]
        model.addConstr(sum_t == 1, f"Receive_one_truck_{l}")

    # Optimize
    model.optimize()

    if model.status == GRB.OPTIMAL:
