from gurobipy import GRB

env = None
model = gp.Model(env=env)

# Sets
zones = ['A', 'B', 'C']
vans = [1, 2]

# Parameters
dispatch_cost = {1: 300, 2: 320}
max_capacity = {1: 150, 2: 180}
coeff_op = {1: 0.08, 2: 0.07}
low_batt = {'A': 120, 'B': 120, 'C': 90}

# Decision Variables
x = model.addVars(vans, zones, vtype=GRB.INTEGER, lb=0)
y = model.addVars(vans, zones, vtype=GRB.BINARY)

# Objective Function
model.setObjective(
    gp.quicksum(dispatch_cost[v] * y[v,z] for v in vans for z in zones) +
    gp.quicksum(coeff_op[v] * (x[v,z])**2 for v in vans for z in zones),
    GRB.MINIMIZE
)

# Constraints
for z in zones:
    model.addConstr(
        gp.quicksum(x[v,z] for v in vans) >= low_batt[z],
        f"Service_{z}"
    )

for v in vans:
    for z in zones:
        model.addConstr(
            x[v,z] <= max_capacity[v],
            f"Capacity_{v}_{z}"
        )
        model.addConstr(
            (x[v,z] > 0).implies(y[v,z] == 1),
            f"DispatchImply_{v}_{z}"
        )

for z in zones:
    model.addConstr(
        gp.quicksum(y[v,z] for v in vans) >= 1,
        f"AtLeastOneVan_{z}"
    )

