import gurobipy as gp
from gurobipy import GRB

model = gp.Model(env=env)

# Parameters
farms = ['A', 'B', 'C']
stores = [1, 2, 3, 4]

production_cost = {'A': 100, 'B': 120, 'C': 150}
yield_capacity = {'A': 500, 'B': 400, 'C': 600}
water_usage = {'A': 6, 'B': 8, 'C': 6}
fertilizer_usage = {'A': 5, 'B': 4, 'C': 3}

transportation_cost = {
    'A': [20, 25, 30, 15],
    'B': [22, 26, 32, 18],
    'C': [18, 24, 28, 14]
}

demand = {1: 200, 2: 300, 3: 400, 4: 500}

# Decision variables
x = {}
for F in farms:
    for S in stores:
        x[F, S] = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name=f"x_{F}_{S}")

# Objective function
obj_expr = gp.LinExpr()
for F in farms:
    for S in stores:
        cost_per_ton = production_cost[F] + transportation_cost[F][S-1]
        obj_expr.addTerm(cost_per_ton, x[F, S])
model.setObjective(obj_expr, GRB.MINIMIZE)

# Constraints
# Demand constraints
for S in stores:
    expr = gp.LinExpr()
    for F in farms:
        expr.addTerm(1, x[F, S])
    model.addConstr(expr >= demand[S], f"demand_store_{S}")

# Production capacity constraints
for F in farms:
    expr = gp.LinExpr()
    for S in stores:
        expr.addTerm(1, x[F, S])
    model.addConstr(expr <= yield_capacity[F], f"production_capacity_{F}")

# Water usage constraint
expr_water = gp.LinExpr()
for F in farms:
    for S in stores:
        expr_water.addTerm(water_usage[F] - 7, x[F, S])
model.addConstr(expr_water <= 0, "water_usage")

# Fertilizer usage constraint
expr_fertilizer = gp.LinExpr()
for F in farms:
    for S in stores:
        expr_fertilizer.addTerm(fertilizer_usage[F] - 4, x[F, S])
model.addConstr(expr_fertilizer <= 0, "fertilizer_usage")

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
