import gurobipy as gp
from gurobipy import GRB

# Parameters
solvents = ['Standard', 'Premium']
raw_materials = ['Alpha', 'Beta', 'Gamma', 'Delta', 'Epsilon']

avail = {
    'Alpha': 12000,
    'Beta': 10500,
    'Gamma': 8000,
    'Delta': 5000,
    'Epsilon': 1e9  # Represents unlimited
}

costs = {
    'Alpha': 15,
    'Beta': 12,
    'Gamma': 10,
    'Delta': 18,
    'Epsilon': 16
}

prices = {
    'Standard': 25.50,
    'Premium': 28.75
}

properties = {
    'Alpha': {'VI': 95, 'FP': 45, 'BP': 150, 'Density': 0.85},
    'Beta': {'VI': 88, 'FP': 55, 'BP': 180, 'Density': 0.92},
    'Gamma': {'VI': 82, 'FP': 60, 'BP': 200, 'Density': 0.89},
    'Delta': {'VI': 105, 'FP': 40, 'BP': 130, 'Density': 0.87},
    'Epsilon': {'VI': 100, 'FP': 50, 'BP': 160, 'Density': 0.91}
}

demands = {
    'Standard': 8.5,
    'Premium': 25
}

# Requirements
vi_min = {'Standard': 85, 'Premium': 92}
fp_exact = {'Standard': 50, 'Premium': 50}
bp_min = {'Standard': 140, 'Premium': 140}
density_exact = {'Standard': 0.88, 'Premium': 0.88}

# Create model
model = gp.Model(env=env)

# Decision variables
x = {}
for r in raw_materials:
    for s in solvents:
        if r == 'Epsilon':
            ub = 1e9
        else:
            ub = avail[r]
        x[r, s] = model.addVar(lb=0, ub=ub, vtype=GRB.CONTINUOUS, name=f"x_{r}_{s}")

# Objective function
revenue = sum(prices[s] * gp.quicksum(x[r, s] for r in raw_materials) for s in solvents)
cost = sum(costs[r] * gp.quicksum(x[r, s] for s in solvents) for r in raw_materials)
model.setObjective(revenue - cost, GRB.MAXIMIZE)

# Property constraints
for s in solvents:
    # Viscosity Index constraint
    model.addConstr(gp.quicksum(properties[r]['VI'] * x[r, s] for r in raw_materials) >= vi_min[s] * gp.quicksum(x[r, s] for r in raw_materials), f"VI_{s}")

    # Flash Point exact constraint
    model.addConstr(gp.quicksum(properties[r]['FP'] * x[r, s] for r in raw_materials) == fp_exact[s] * gp.quicksum(x[r, s] for r in raw_materials), f"FP_{s}")

    # Boiling Point constraint
    model.addConstr(gp.quicksum(properties[r]['BP'] * x[r, s] for r in raw_materials) >= bp_min[s] * gp.quicksum(x[r, s] for r in raw_materials), f"BP_{s}")

    # Density exact constraint
    model.addConstr(gp.quicksum(properties[r]['Density'] * x[r, s] for r in raw_materials) == density_exact[s] * gp.quicksum(x[r, s] for r in raw_materials), f"Density_{s}")

# Raw material availability constraints
for r in raw_materials:
    if r != 'Epsilon':
        model.addConstr(gp.quicksum(x[r, s] for s in solvents) <= avail[r], f"Avail_{r}")

# Beta usage limit constraint
for s in solvents:
    beta_usage = x['Beta', s]
    total_s = gp.quicksum(x[r, s] for r in raw_materials)
    model.addConstr(beta_usage <= 0.35 * total_s, f"Beta_limit_{s}")

# Demand constraints
for s in solvents:
    model.addConstr(gp.quicksum(x[r, s] for r in raw_materials) >= demands[s], f"Demand_{s}")

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
