w = {}
for g in range(1, 5):
    w[g] = model.addVar(lb=0, vtype=GRB.INTEGER, name=f"wg_{g}")

a = {q: {} for q in range(1, 5)}
b = {q: {} for q in range(1, 5)}
for q in range(1, 5):
    for g in range(1, 5):
        if q != g:
            a[q][g] = model.addVar(lb=0, vtype=GRB.INTEGER, name=f"a_q{q}_g{g}")
            b[q][g] = model.addVar(lb=0, vtype=GRB.INTEGER, name=f"b_q{q}_g{g}")

i = {'A': {}, 'B': {}}
for p in ['A', 'B']:
    for q in range(1, 5):
        i[p][q] = model.addVar(lb=0, vtype=GRB.INTEGER, name=f"i_{p}_q{q}")

# Constraints
for g in range(1, 5):
    total = 0
    for q in range(1, 5):
        if q != g:
            total += a[q][g] + b[q][g]
    model.addConstr(total == w[g], f"group_{g}_total")

