prices = {
    'C1': {'S1': 12, 'S2': 14, 'S3': 13},
    'C2': {'S1': 15, 'S2': 16, 'S3': 14},
    'C3': {'S1': 18, 'S2': 17, 'S3': 19},
    'C4': {'S1': 20, 'S2': 19, 'S3': 18},
    'C5': {'S1': 22, 'S2': 21, 'S3': 20}
}

reliability = {'S1': 0.85, 'S2': 0.75, 'S3': 0.90}
capacities = {'S1': 2000, 'S2': 1800, 'S3': 2500}
demand = {'C1': 1200, 'C2': 800, 'C3': 1500, 'C4': 900, 'C5': 600}

# Create the model
model = gp.Model(env=env)

