from gurobipy import GRB

model = gp.Model(env=env)

# Define sets and indices
Mines = ['M1', 'M2', 'M3', 'M4']
Plants = ['P1', 'P2', 'P3']

# Decision variables
X = {}
for M in Mines:
    for P in Plants:
        X[M, P] = model.addVar(lb=0, name=f"{M}_{P}")

# Parameters
Q_M = {'M1': 6000, 'M2': 9000, 'M3': 7000, 'M4': 5000}
C_P = {'P1': 8000, 'P2': 10000, 'P3': 12000}
R_M = {'M1': 0.85, 'M2': 0.92, 'M3': 0.78, 'M4': 0.88}
CT = {
    ('M1', 'P1'): 4, ('M1', 'P2'): 6, ('M1', 'P3'): 5,
    ('M2', 'P1'): 7, ('M2', 'P2'): 5, ('M2', 'P3'): 8,
    ('M3', 'P1'): 3, ('M3', 'P2'): 4, ('M3', 'P3'): 6,
    ('M4', 'P1'): 8, ('M4', 'P2'): 6, ('M4', 'P3'): 7
}
CProc = {'M1': 12, 'M2': 18, 'M3': 10, 'M4': 15}
MAX_SULFUR = 0.015
BUDGET = 500000

S_M = {'M1': 0.012, 'M2': 0.008, 'M3': 0.021, 'M4': 0.015}

# Objective function
obj_expr = 0
for M in Mines:
    total_X_M = gp.quicksum(X[M, P] for P in Plants)
    obj_expr += R_M[M] * total_X_M

model.setObjective(obj_expr, GRB.MAXIMIZE)

# Constraints
# Supply constraints
for M in Mines:
    lhs = gp.quicksum(X[M, P] for P in Plants)
    model.addConstr(lhs <= Q_M[M], name=f"supply_{M}")

# Demand constraints
for P in Plants:
    lhs = gp.quicksum(X[M, P] for M in Mines)
    model.addConstr(lhs <= C_P[P], name=f"demand_{P}")

# Budget constraint
budget_expr = 0
for M in Mines:
    for P in Plants:
        budget_expr += (CT[(M, P)] + CProc[M]) * X[M, P]
model.addConstr(budget_expr <= BUDGET, name="budget")

# Sulfur content constraint
sulfur_diff = {M: S_M[M] - MAX_SULFUR for M in Mines}
sulfur_expr = 0
for M in Mines:
    for P in Plants:
        sulfur_expr += sulfur_diff[M] * X[M, P]
model.addConstr(sulfur_expr <= 0, name="sulfur_limit")

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
