import gurobipy as gp
from gurobipy import GRB

# Precompute p_C_H for each city and hospital
p = {}
hospitals = ['H1', 'H2', 'H3']
cities = ['C1', 'C2', 'C3', 'C4']

for c in cities:
    p[c] = {}
    for h in hospitals:
        if c == 'C1':
            d = {'H1': 50, 'H2': 80, 'H3': 120}[h]
        elif c == 'C2':
            d = {'H1': 60, 'H2': 40, 'H3': 90}[h]
        elif c == 'C3':
            d = {'H1': 110, 'H2': 70, 'H3': 50}[h]
        else:  # C4
            d = {'H1': 130, 'H2': 100, 'H3': 60}[h]
        p[c][h] = 1 - 0.00005 * (d ** 2)

# Create model
model = gp.Model(env=env)

# Decision variables
x = {c: model.addVar(lb=0, ub=1, vtype=GRB.BINARY, name=f"x_{c}") for c in cities}
y = {}
for c in cities:
    for h in hospitals:
        y[(c, h)] = model.addVar(lb=0, ub=1, vtype=GRB.BINARY, name=f"y_{c}_{h}")

# Objective
model.setObjective(sum(c_C * x[c] for c, c_C in zip(['C1', 'C2', 'C3', 'C4'], [8, 7, 9, 7.5])), GRB.MINIMIZE)

# Constraints
# 1. Select exactly two cities
model.addConstr(sum(x[c] for c in cities) == 2, name="select_two_cities")

# 2. Each hospital is served by at least one center
for h in hospitals:
    model.addConstr(sum(y[(c, h)] for c in cities) >= 1, name=f"hospital_{h}_served")

# 3. A city can only serve a hospital if it's selected
for c in cities:
    for h in hospitals:
        model.addConstr(y[(c, h)] <= x[c], name=f"y_le_x_{c}_{h}")

# 4. Reliability constraints
for h in hospitals:
    # Get all pairs of cities that could serve this hospital
    city_pairs = [(c1, c2) for c1 in cities for c2 in cities if c1 < c2]
    # Add constraint for each pair
    for c1, c2 in city_pairs:
        model.addConstr(
            (1 - p[c1][h]) * (1 - p[c2][h]) <= 0.1,
            name=f"reliability_{h}_{c1}_{c2}"
        )

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
