import gurobipy as gp
from gurobipy import GRB

model = gp.Model(env=env)

# Parameters
d = {'A': 120, 'B': 120, 'C': 90}
f = {1: 300, 2: 320}
h = {1: 0.08, 2: 0.07}
gv_dict = {1: 150, 2: 180}

# Variables
x = {}
for v in [1, 2]:
    x[v] = {}
    for z in ['A', 'B', 'C']:
        ub = gv_dict[v]
        x[v][z] = model.addVar(lb=0, ub=ub, vtype=GRB.INTEGER)
y = {v: model.addVar(vtype=GRB.BINARY) for v in [1, 2]}

# Constraints
# Zone demand constraints
for z in ['A', 'B', 'C']:
    model.addConstr(x[1][z] + x[2][z] == d[z], name=f"zone_{z}")

# Van capacity constraints
for v in [1, 2]:
    sum_x = gp.quicksum(x[v][z] for z in ['A', 'B', 'C'])
    model.addConstr(sum_x <= gv_dict[v], name=f"van_{v}_cap")

# Dispatch condition constraints
for v in [1, 2]:
    sum_x = gp.quicksum(x[v][z] for z in ['A', 'B', 'C'])
    model.addConstr(sum_x <= gv_dict[v] * (1 - y[v]), name=f"dispatch_{v}")

# Objective function
objective = 0
for v in [1, 2]:
    objective += f[v] * y[v]
    sum_xv = gp.quicksum(x[v][z] for z in ['A', 'B', 'C'])
    objective += h[v] * (sum_xv ** 2)

model.setObjective(objective, GRB.MINIMIZE)
model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
